  function renderConversations(){
    const scenario=conversationScenarios.find(item=>item.id===state.conversationId)||conversationScenarios[0];
    const turns=scenario.turns;
    const step=state.conversationStep;
    const done=state.conversationComplete[scenario.id]===true;
    const helpTextFor=(item)=>state.help==="bn"?item.bn:item.en;
    const progress=turns.map((_,index)=>'<span class="cafe-progress-segment '+(index<step||done?'done':index===step&&!done?'current':'')+'"></span>').join("");
    const scenarioCards=conversationScenarios.map(item=>'<button class="conversation-scenario-card '+(item.id===scenario.id?'is-active':'')+'" data-conversation="'+item.id+'" aria-pressed="'+(item.id===scenario.id)+'"><span class="conversation-card-image"><img src="'+escapeHTML(item.image)+'" alt=""/><span>'+item.icon+'</span></span><span class="conversation-card-copy"><small>'+escapeHTML(item.level)+' · '+item.turns.length+' TURNS</small><strong>'+escapeHTML(item.title)+'</strong><span>'+escapeHTML(item.detail)+'</span><em>'+(state.conversationComplete[item.id]?'✓ Completed · practise again':item.id===scenario.id?'Selected scene':'Choose this scene')+'</em></span></button>').join("");
    let activity="";
    if(done){
      activity='<div class="cafe-finished"><div class="cafe-finished-mark">✓</div><p class="cafe-eyebrow">ROLE-PLAY COMPLETE</p><h2>'+escapeHTML(scenario.finishTitle)+'</h2><p>'+escapeHTML(scenario.finishText)+'</p><div class="cafe-recap">'+turns.map(item=>{const phrase=item.choices.find(choice=>choice.correct);return '<button class="cafe-recap-phrase" data-speak="'+escapeHTML(phrase.fi)+'"><span>▶</span><strong>'+escapeHTML(phrase.fi)+'</strong><small>'+escapeHTML(helpTextFor(phrase))+'</small></button>'}).join("")+'</div><button class="button-secondary" data-conversation-action="restart">'+escapeHTML(scenario.restart)+' ↺</button></div>';
    }else{
      const answered=state.conversationAnswered;
      const turn=turns[step];
      const picked=turn.choices.find(choice=>choice.fi===state.conversationChoice);
      const correct=picked?.correct===true;
      const options=turn.choices.map(choice=>'<button class="cafe-choice '+(answered&&choice.correct?'correct':'')+' '+(answered&&choice.fi===state.conversationChoice&&!choice.correct?'incorrect':'')+'" data-conversation-choice="'+escapeHTML(choice.fi)+'" '+(answered?'disabled':'')+'><strong>'+escapeHTML(choice.fi)+'</strong><span>'+escapeHTML(helpTextFor(choice))+'</span></button>').join("");
      const feedback=answered?'<div class="cafe-feedback '+(correct?'right':'wrong')+'" role="status">'+(correct?'Perfect — that sounds natural.':'Good try. Listen once more, then choose a different phrase.')+'</div><button class="'+(correct?'button-primary':'button-secondary')+'" data-conversation-action="'+(correct?'continue':'retry')+'">'+(correct?(step===turns.length-1?'Finish conversation':'Continue conversation'):'Try again')+' <span>'+(correct?'→':'↺')+'</span></button>':'';
      activity='<div class="cafe-conversation"><div class="cafe-step-label"><span>YOUR TURN</span><small>Moment '+(step+1)+' of '+turns.length+'</small></div><div class="cafe-barista"><div class="barista-avatar" aria-hidden="true">'+scenario.icon+'</div><div class="barista-line"><span class="speaker-label">'+escapeHTML(scenario.staff)+' · FINNISH</span><p>'+escapeHTML(turn.prompt)+'</p><small>'+escapeHTML(helpTextFor(turn))+'</small></div><button class="cafe-listen" data-speak="'+escapeHTML(turn.prompt)+'" aria-label="Listen to '+escapeHTML(scenario.staff.toLowerCase())+'">▶</button></div><h2>What would you say?</h2><p class="cafe-instruction">Choose the Finnish phrase that fits. Listen to each phrase before you answer.</p><div class="cafe-choices">'+options+'</div>'+feedback+'</div>';
    }
    pageContent.innerHTML='<div class="page-title-row"><div><div class="page-kicker">Everyday Finnish, one gentle step at a time</div><h1>Conversation practice</h1><p>Choose a scene, listen to the Finnish, and try a useful response.</p></div><span class="cafe-level-pill">2 SCENES · PRE-A1–A1</span></div><section class="conversation-picker"><div class="section-head"><div><h2>Choose a situation</h2><p>Practise words you can use while exploring Finland.</p></div></div><div class="conversation-scenarios">'+scenarioCards+'</div></section><section class="cafe-hero"><img src="'+escapeHTML(scenario.image)+'" alt="'+escapeHTML(scenario.alt)+'"/><div class="cafe-hero-shade"></div><div class="cafe-hero-copy"><span>'+escapeHTML(scenario.label)+'</span><h2>'+escapeHTML(scenario.heading)+'</h2><p>'+escapeHTML(scenario.intro)+'</p><div class="cafe-hero-note">'+scenario.icon+' &nbsp; Speak it, hear it, remember it.</div></div></section><div class="cafe-progress" aria-label="Conversation progress">'+progress+'</div><section class="cafe-panel">'+activity+'</section><div class="cafe-footer-note"><span>✿</span><p>Finnish TTS uses the voice installed in your browser. Your conversation progress stays on this device.</p></div>';
  }
