    const pairs=[{first:"tuli",firstMeaning:"fire · আগুন",second:"tuuli",secondMeaning:"wind · বাতাস",focus:"Vowel length",note:"Hold the double u a little longer."},{first:"tuli",firstMeaning:"fire · আগুন",second:"tulli",secondMeaning:"customs · শুল্ক বিভাগ",focus:"Consonant length",note:"Hold the double l a little longer."}];
