    const question=soundQuiz[state.soundStep]||soundQuiz[0];
    const quizMarkup=state.soundsComplete?`<div class="sound-complete"><span>✓</span><div><strong>Sound foundations complete</strong><p>Nice work. You can revisit these sounds whenever you like.</p></div><button class="button-secondary" data-sound-action="restart">Practise again ↻</button></div>`:`<section class="sound-quiz"><div class="sound-quiz-top"><div><span class="review-kicker">A QUICK CHECK · ${state.soundStep+1} OF ${soundQuiz.length}</span><h2>Try what you heard</h2></div><span class="sound-quiz-time">1 minute</span></div><div class="sound-quiz-progress" aria-label="Question ${state.soundStep+1} of ${soundQuiz.length}"><span style="width:${Math.round((state.soundStep/soundQuiz.length)*100)}%"></span></div><p class="sound-quiz-question">${state.help==="bn"?question.questionBn:question.question}</p><div class="sound-quiz-options">${question.choices.map(choice=>`<button class="quiz-option ${state.soundAnswered&&choice===question.answer?"correct":""} ${state.soundAnswered&&choice===state.soundChoice&&choice!==question.answer?"incorrect":""}" data-sound-choice="${choice}" ${state.soundAnswered?"disabled":""}>${choice}</button>`).join("")}</div>${state.soundAnswered?`<div class="quiz-feedback ${state.soundChoice===question.answer?"":"wrong"}" role="status">${state.soundChoice===question.answer?(state.help==="bn"?question.whyBn:question.why):(state.help==="bn"?"আরেকবার শুনে আবার চেষ্টা করুন।":"Listen once more and try again.")}</div><button class="${state.soundChoice===question.answer?"button-primary":"button-secondary"}" data-sound-action="${state.soundChoice===question.answer?"continue":"retry"}">${state.soundChoice===question.answer?(state.soundStep===soundQuiz.length-1?"Finish sound lab":"Next question"):"Try again"} <span>${state.soundChoice===question.answer?"→":"↺"}</span></button>`:""}</section>`;
    pageContent.innerHTML=`<div class="page-title-row"><div><div class="page-kicker">PRE-A1 · LISTEN, LOOK, REPEAT</div><h1>Finnish sound lab</h1><p>Meet the eight Finnish vowels, then hear how a longer sound can change a word.</p></div><span class="cafe-level-pill">3 MINUTES · BEGINNER</span></div><section class="sound-lab-hero"><img src="${photo.summer}" alt="Quiet Finnish lake surrounded by forest"/><div class="sound-lab-hero-copy"><span>START WITH THE SOUND</span><h2>Every letter has a place in the word.</h2><p>Tap a speaker, listen once, and say the word at your own pace. No score and no rush.</p><div class="sound-hero-note">🌲 &nbsp; A calm first step into Finnish</div></div></section><section class="sound-map-section"><div class="section-head"><div><span class="review-kicker">THE FINNISH VOWEL MAP</span><h2>Eight vowels, one small sound at a time</h2><p>Listen to each vowel inside a familiar word. Ä, ö, and y are full letters in Finnish.</p></div></div><div class="sound-vowel-grid">${vowelCards}</div><div class="sound-groups-note"><span><b>Back</b> a · o · u</span><span><b>Neutral</b> e · i</span><span><b>Front</b> y · ä · ö</span></div></section><section class="sound-compare-section"><div class="section-head"><div><span class="review-kicker">SLOW DOWN AND NOTICE</span><h2>One extra letter can change the word</h2><p>Press each word, then compare the short and long sounds.</p></div></div><div class="sound-pair-grid">${pairCards}</div></section>${quizMarkup}<div class="sound-source-note">Practice ideas follow beginner pronunciation lessons from <a href="https://openlearning.aalto.fi/mod/page/view.php?id=17025" target="_blank" rel="noreferrer">Aalto OpenLearning ↗</a> and <a href="https://www.utu.fi/en/fi/yliopisto/kieli-ja-viestintaopintojen-keskus/tutkimus-ja-kehittaminen/osus/opetusvideot" target="_blank" rel="noreferrer">University of Turku ↗</a>. Finnish audio uses the voice available in your browser.</div>`;
